/**
 * Custom Worker entry (OpenNext "custom worker" pattern): the OpenNext-generated fetch handler,
 * plus a `scheduled` handler for the cron trigger in wrangler.jsonc (every 15 min) that drains
 * the waiting-list notification outbox (lib/jobs/scheduled.ts). `npm run cf:build` must run
 * first so .open-next/worker.js exists; wrangler bundles this file as `main`.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build` (no type declarations).
import { default as openNext } from "./.open-next/worker.js";
import { runScheduled } from "./lib/jobs/scheduled";

// Durable Object classes the generated worker exports (unused by this app's config, re-exported for parity).
// @ts-expect-error — generated by `opennextjs-cloudflare build`.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

const handler = {
  fetch: (openNext as ExportedHandler<CloudflareEnv>).fetch,
  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runScheduled(env).then(() => undefined));
  },
} satisfies ExportedHandler<CloudflareEnv>;

export default handler;
